import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Cd7mb1YL.js";const u=JSON.parse('{"title":"Mawy","titleTemplate":"A Markdown editor and viewer in one package","description":"A Markdown editor and viewer in one package. Write in WYSIWYG or in the source, switch between them freely, and show the finished document through a read-only viewer.","frontmatter":{"layout":"home","title":"Mawy","titleTemplate":"A Markdown editor and viewer in one package","description":"A Markdown editor and viewer in one package. Write in WYSIWYG or in the source, switch between them freely, and show the finished document through a read-only viewer.","hero":{"name":"Mawy","text":"One document, three ways of looking at it","tagline":"A Markdown editor and viewer in one package. Write with the document in front of you as it will look, or switch to the Markdown source and work on that. When the document is finished, a read-only viewer shows it exactly as it looked while you were writing it.","image":{"src":"/256x256.png","alt":"Mawy","width":200,"height":200},"actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Try it","link":"/guide/playground"},{"theme":"alt","text":"API","link":"/api/"},{"theme":"alt","text":"GitHub","link":"https://github.com/jooy2/mawy"}]},"features":[{"title":"Write it as it will look","details":"The WYSIWYG surface shows the finished document while you are still writing it, with headings at the size they will be, the table laid out and the image in place. There is no separate preview step.","link":"/guide/editor","linkText":"The editor"},{"title":"Or write the Markdown","details":"Switch to the source whenever the rendered view is in the way, such as a table that will not lay out or a block you want to paste in whole. Both surfaces edit the same document, so nothing is lost in the move.","link":"/guide/editor","linkText":"The editor"},{"title":"Then hand it to a reader","details":"When the writing is done, the viewer shows the same document and nothing else. What a reader sees is what the author had in front of them, down to the line breaks.","link":"/guide/viewer","linkText":"The viewer"},{"title":"Nothing to assemble first","details":"One package and one line of CSS. There is no theme file to fill in, no build-side plugin, and no second library to render what you wrote.","link":"/guide/getting-started","linkText":"Getting started"}]},"headers":[],"relativePath":"index.md","filePath":"en/index.md","lastUpdated":1788614595000}'),n={name:"index.md"};function o(s,e,d,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="where-it-stands" tabindex="-1">Where it stands <a class="header-anchor" href="#where-it-stands" aria-label="Permalink to &quot;Where it stands&quot;">​</a></h2><p>Mawy is at <code>1.0.0</code>. Its own parser reads CommonMark and GitHub&#39;s additions, <code>MawyViewer</code> draws the result, and <code>MawyEditor</code> puts the Markdown source, a live preview and a formatting toolbar around the same string. The demos on <a href="./guide/editor">the editor</a> and <a href="./guide/viewer">the viewer</a> pages run those components.</p><p>It is published as two packages: <a href="https://www.npmjs.com/package/mawy-react" target="_blank" rel="noreferrer"><code>mawy-react</code></a> on npm and <a href="https://pub.dev/packages/mawy" target="_blank" rel="noreferrer"><code>mawy</code></a> on pub.dev. They are one library. The Dart parser and the TypeScript parser implement the same rules in the same functions, and a check in the repository diffs both parsers&#39; trees over every document in it. Both have the viewer and the editor. The Flutter editor has three surfaces where the React one has four, and the editor page says why. Pick yours in the sidebar; it changes what every page here says.</p><p>The <code>wysiwyg</code> surface, which edits the drawn document in place, is on the React editor&#39;s default list of surfaces. Both packages are published at <code>1.0.0</code>. From here the exported API is under semantic versioning, so a name only goes away or changes shape in a major version.</p><p><a href="./guide/getting-started">Getting started</a> has what exists today, and the <a href="./changelog">changelog</a> records each release.</p>',5)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
